use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,process::{Command,Stdio}};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/tmp/zopro-g2-tree-c7a");let mut complete=read(r.join("local-output/preflight/complete.json"));assert_eq!(complete["status"],"complete");assert_eq!(complete["raw_query_calls"],32);assert_eq!(complete["processes"],8);assert_eq!(complete["oracle_checks_passed"],true);assert_eq!(hash(r.join("local-output/preflight/analysis.json")),complete["analysis_sha256"].as_str().unwrap());complete["source_manifest_sha256"]=json!(hash(r.join("context/manifest.json")));complete["same_prover_binaries_in_final_image"]=json!(true);fs::write(r.join("preflight-complete.json"),serde_json::to_vec_pretty(&complete).unwrap()).unwrap();let ctx=r.join("final-context");fs::create_dir(&ctx).unwrap();fs::copy(r.join("preflight-complete.json"),ctx.join("preflight-complete.json")).unwrap();fs::write(ctx.join("Dockerfile"),"FROM zopro-g2-tree-c7a:preflight\nCOPY preflight-complete.json /gt/preflight-complete.json\n").unwrap();let stamp=Command::new("date").args(["-u","+%Y%m%d-%H%M%S"]).output().unwrap();assert!(stamp.status.success());let id=format!("gt-c7a-{}",String::from_utf8(stamp.stdout).unwrap().trim());assert!(id.chars().all(|c|c.is_ascii_alphanumeric()||c=='-'));let tag=format!("558215002830.dkr.ecr.eu-north-1.amazonaws.com/zolana-prover:bench-{id}");let log=fs::File::create(r.join("docker-final-build.log")).unwrap();assert!(Command::new("docker").args(["build","--pull=false","-t",&tag]).arg(&ctx).stdout(Stdio::from(log.try_clone().unwrap())).stderr(Stdio::from(log)).status().unwrap().success());let o=Command::new("docker").args(["image","inspect",&tag,"--format","{{.Id}}"] ).output().unwrap();assert!(o.status.success());fs::write(r.join("run-id.txt"),&id).unwrap();fs::write(r.join("image-manifest.json"),serde_json::to_vec_pretty(&json!({"status":"local preflight complete; not published or launched","image_tag":tag,"image_id":String::from_utf8(o.stdout).unwrap().trim(),"run_id":id,"local_preflight_raw_calls":32,"local_preflight_processes":8,"oracle_checks_passed":true,"SDK_proofs":0,"Gnark_exports":0,"preflight_receipt_sha256":hash(r.join("preflight-complete.json")),"container_manifest_sha256":hash(r.join("context/manifest.json"))})).unwrap()).unwrap();println!("Prepared {tag};8oracle preflights/32raw calls;no cloud resources");}
